+            for (int k = 0; k < m1.size(); k++) {
+                FType a = deRest(m1.get(k));
+                FType b = deRest(m2.get(k));
+                if (a instanceof GenericTypeInstance && b instanceof GenericTypeInstance && sameGeneric(a, b)
